class VideoSharingPlatform {
    private java.util.Map<Integer, String> videos = new java.util.HashMap<>();
    private java.util.Map<Integer, int[]> stats = new java.util.HashMap<>();
    private java.util.PriorityQueue<Integer> available = new java.util.PriorityQueue<>();
    private int nextId = 0;
    public VideoSharingPlatform() {}
    public int upload(String video) {
        int id = available.isEmpty() ? nextId++ : available.poll();
        videos.put(id, video); stats.put(id, new int[3]);
        return id;
    }
    public void remove(int videoId) {
        if (videos.containsKey(videoId)) { videos.remove(videoId); stats.remove(videoId); available.offer(videoId); }
    }
    public String watch(int videoId, int startMinute, int endMinute) {
        if (!videos.containsKey(videoId)) return "-1";
        stats.get(videoId)[0]++;
        String v = videos.get(videoId);
        return v.substring(startMinute, Math.min(endMinute + 1, v.length()));
    }
    public void like(int videoId) { if (stats.containsKey(videoId)) stats.get(videoId)[1]++; }
    public void dislike(int videoId) { if (stats.containsKey(videoId)) stats.get(videoId)[2]++; }
    public int[] getLikesAndDislikes(int videoId) {
        if (!stats.containsKey(videoId)) return new int[]{-1};
        return new int[]{stats.get(videoId)[1], stats.get(videoId)[2]};
    }
    public int getViews(int videoId) {
        return stats.containsKey(videoId) ? stats.get(videoId)[0] : -1;
    }
}

import java.util.*;

class VideoSharingPlatform {
    private Map<Integer, String> videos;
    private Map<Integer, int[]> stats;
    private TreeSet<Integer> available;
    private int nextId;
    public VideoSharingPlatform() {
        videos = new HashMap();
        stats = new HashMap();
        available = new TreeSet();
        nextId = 0;
    }
    public int upload(String video) {
        int id;
        if (!available.isEmpty()) {
            id = available.first().intValue();
            available.remove(available.first());
        } else {
            id = nextId++;
        }
        videos.put(id, video);
        stats.put(id, new int[3]);
        return id;
    }
    public void remove(int videoId) {
        if (videos.containsKey(videoId)) {
            videos.remove(videoId);
            stats.remove(videoId);
            available.add(videoId);
        }
    }
    public String watch(int videoId, int startMinute, int endMinute) {
        if (!videos.containsKey(videoId)) return "-1";
        stats.get(videoId)[0]++;
        String v = videos.get(videoId);
        return v.substring(startMinute, Math.min(endMinute + 1, v.length()));
    }
    public void like(int videoId) {
        if (stats.containsKey(videoId)) stats.get(videoId)[1]++;
    }
    public void dislike(int videoId) {
        if (stats.containsKey(videoId)) stats.get(videoId)[2]++;
    }
    public int[] getLikesAndDislikes(int videoId) {
        if (!stats.containsKey(videoId)) return new int[]{-1};
        return new int[]{stats.get(videoId)[1], stats.get(videoId)[2]};
    }
    public int getViews(int videoId) {
        return stats.containsKey(videoId) ? stats.get(videoId)[0] : -1;
    }
}
